CREATE TABLE merchant_accounts(workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id),request_id TEXT NOT NULL UNIQUE,actor_id TEXT NOT NULL REFERENCES users(id),country TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('requested','submitted','bound')),account_id TEXT UNIQUE,created_at INTEGER NOT NULL,submitted_at INTEGER NOT NULL DEFAULT 0,snapshot BLOB, observation_generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE merchant_products(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),request_key TEXT NOT NULL,name TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('eur','usd','gbp')),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 50 AND 99999999),active INTEGER NOT NULL CHECK(active IN (0,1)),revision INTEGER NOT NULL CHECK(revision>0),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,request_key));
CREATE INDEX merchant_products_workspace ON merchant_products(workspace_id,id);
CREATE TABLE merchant_orders(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),product_id TEXT NOT NULL REFERENCES merchant_products(id),product_revision INTEGER NOT NULL,buyer_hash TEXT NOT NULL,request_key TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES merchant_accounts(account_id),name TEXT NOT NULL,currency TEXT NOT NULL,amount_minor INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('requested','submitted','open','complete','expired')),payment_status TEXT NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid')),session_id TEXT,checkout_url TEXT NOT NULL DEFAULT '',payment_intent_id TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,submitted_at INTEGER NOT NULL DEFAULT 0,observation_generation INTEGER NOT NULL DEFAULT 0,observed_at INTEGER NOT NULL DEFAULT 0, fulfilled_at INTEGER NOT NULL DEFAULT 0, fulfilled_by TEXT NOT NULL DEFAULT '',UNIQUE(buyer_hash,request_key),UNIQUE(account_id,session_id));
CREATE INDEX merchant_orders_workspace ON merchant_orders(workspace_id,created_at,id);
CREATE INDEX merchant_orders_buyer ON merchant_orders(buyer_hash,created_at);
CREATE TABLE merchant_events(id TEXT PRIMARY KEY,account_id TEXT NOT NULL,order_id TEXT NOT NULL REFERENCES merchant_orders(id),session_id TEXT NOT NULL,event_type TEXT NOT NULL,body_hash TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','done')),created_at INTEGER NOT NULL,received_at INTEGER NOT NULL,next_attempt INTEGER NOT NULL DEFAULT 0, refund_request_id TEXT NOT NULL DEFAULT '', provider_refund_id TEXT NOT NULL DEFAULT '');
CREATE INDEX merchant_events_due ON merchant_events(state,next_attempt,id);
CREATE TABLE merchant_refunds(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES merchant_orders(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),actor_id TEXT NOT NULL,account_id TEXT NOT NULL,payment_intent_id TEXT NOT NULL,currency TEXT NOT NULL,amount_minor INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('requested','submitted','pending','requires_action','succeeded','failed','canceled')),provider_id TEXT,created_at INTEGER NOT NULL,submitted_at INTEGER NOT NULL DEFAULT 0,observed_at INTEGER NOT NULL DEFAULT 0,generation INTEGER NOT NULL DEFAULT 0,UNIQUE(account_id,provider_id));
CREATE INDEX merchant_refunds_workspace ON merchant_refunds(workspace_id,created_at);
CREATE TABLE merchant_buyer_sessions(token_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE INDEX merchant_buyer_sessions_expiry ON merchant_buyer_sessions(expires_at);
CREATE TABLE merchant_order_recovery_codes(order_id TEXT PRIMARY KEY REFERENCES merchant_orders(id) ON DELETE CASCADE,code_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL);
CREATE TABLE merchant_order_recovery_grants(order_id TEXT NOT NULL REFERENCES merchant_orders(id) ON DELETE CASCADE,session_hash TEXT NOT NULL REFERENCES merchant_buyer_sessions(token_hash) ON DELETE CASCADE,created_at INTEGER NOT NULL,PRIMARY KEY(order_id,session_hash));
CREATE INDEX merchant_order_recovery_grants_session ON merchant_order_recovery_grants(session_hash,order_id);
